/**
 * Builds the station's machines from the catalog and places them in the station frame.
 * @param {object} o
 * @param {object} o.registry  the catalog (components, products, ops)
 * @param {object} o.ctx       build context: materials, belt height
 * @returns {{ root: THREE.Group, equipment: object }}
 */
export function build({ registry, ctx }) {
  const root = new THREE.Group();
  root.name = 'ST3 Electronics Wiring';
  const equipment = {};

  // slab: Epoxy floor slab for a station cell with yellow boundary lines and an... (shell assemblyCell)
  equipment.slab = registry.buildComponent('floorSlab', {
    length: 4.7,
    depth: 3.2,
    walkway: 0.8281250000000001,
  }, ctx);
  root.add(equipment.slab.root);

  // fence: Safety guard fence: yellow posts and rails with wire-mesh panels, running... (shell assemblyCell)
  equipment.fence = registry.buildComponent('guardFence', { length: 4.1000000000000005 }, ctx);
  equipment.fence.root.position.set(0, 0, -1.35);
  root.add(equipment.fence.root);

  // line: Twin-strand pallet conveyor on aluminium profiles, with optional work stop... (shell assemblyCell)
  equipment.line = registry.buildComponent('palletConveyor', {
    length: 4.4,
    carrierLength: 1.2,
    workStop: true,
  }, ctx);
  root.add(equipment.line.root);

  // liftIn: Yellow portal lift unit that moves carriers between the conveyor and the... (shell assemblyCell)
  equipment.liftIn = registry.buildComponent('liftUnit', {}, ctx);
  equipment.liftIn.root.position.set(-1.6, 0, 0);
  root.add(equipment.liftIn.root);

  // liftOut: Yellow portal lift unit that moves carriers between the conveyor and the... (shell assemblyCell)
  equipment.liftOut = registry.buildComponent('liftUnit', {}, ctx);
  equipment.liftOut.root.position.set(1.6, 0, 0);
  root.add(equipment.liftOut.root);

  // sign: Overhead double-sided station sign with the station code and function, on two... (shell assemblyCell)
  equipment.sign = registry.buildComponent('stationSign', {
    code: 'ST3',
    title: 'Electronics Wiring',
    color: '#2f9a4a',
  }, ctx);
  equipment.sign.root.position.set(0, 0, -1.1500000000000001);
  root.add(equipment.sign.root);

  // panel: Pedestal operator panel (HMI) with a live status screen, start/stop buttons... (shell assemblyCell)
  equipment.panel = registry.buildComponent('hmi', {}, ctx);
  equipment.panel.root.position.set(-1.55, 0, 0.95);
  equipment.panel.root.rotation.y = 0.3;
  root.add(equipment.panel.root);

  // beacon: Three-lamp signal tower on a floor pole: green running, amber waiting, red... (shell assemblyCell)
  equipment.beacon = registry.buildComponent('stackLight', {}, ctx);
  equipment.beacon.root.position.set(1.9500000000000002, 0, -0.55);
  root.add(equipment.beacon.root);

  // gantry: Overhead Cartesian gantry (X bridge, Z carriage, Y ram, rotary wrist) with a...
  equipment.gantry = registry.buildComponent('cartesianGantry', {
    spanX: 1.5,
    spanZ: 0.9,
    beamY: 2.3,
    maxGap: 0.22,
    frameColor: 'machineBlue',
    screwdriver: true,
  }, ctx);
  root.add(equipment.gantry.root);

  // harnessBoard: Tilted harness board on two posts with cable harnesses laid between...
  equipment.harnessBoard = registry.buildComponent('harnessBoard', {}, ctx);
  equipment.harnessBoard.root.position.set(0.9, 0, -1.1);
  root.add(equipment.harnessBoard.root);

  // tester: Floor-standing test cabinet (continuity, function test) with display, pass /...
  equipment.tester = registry.buildComponent('testCabinet', {}, ctx);
  equipment.tester.root.position.set(-1.2, 0, -0.75);
  root.add(equipment.tester.root);

  return { root, equipment };
}
